refentry.refsect1:
&reftitle.description;
mixedforward_static_call callablecallback mixedargs
Функция вызывает пользовательскую функцию или метод из параметра callback с произвольным количеством аргументов. Функцию вызывают только в контексте метода; вызов вне класса выдаст фатальную ошибку. При передаче callback-метода в первом аргументе функция выполняет перенаправляющий вызов, поэтому static:: внутри целевого метода разрешается в класс, в контексте которого вызвали функцию, как если бы callback-метод вызвали через языковую конструкцию self:: или parent::.

  &reftitle.examples;



    Пример вызова статического метода и функции функцией forward_static_call


<?php

class A
{
    const NAME = 'A';

    public static function test()
    {
        $args = func_get_args();
        echo static::NAME, ": " . join(', ', $args) . "\n";
    }
}

class B extends A
{
    const NAME = 'B';

    public static function test()
    {
        echo self::NAME, "\n";
        forward_static_call(array('A', 'test'), 'more', 'args');
        forward_static_call('test', 'other', 'args');
    }
}

B::test('foo');

function test()
{
    $args = func_get_args();
    echo "C: " . join(', ', $args) . "\n";
}



    &example.outputs;


B
B: more, args
C: other, args
